#[verus]
fn chebyshev(coef: Vec<i8>) -> ChebyshevPoly {
    // Convert each i8 coefficient to i32, preserving order
    let mut coefs_i32: Vec<i32> = Vec::new();
    let mut idx: usize = 0;
    while idx < coef.len() {
        coefs_i32.push(coef[idx] as i32);
        idx += 1;
    }

    ChebyshevPoly {
        coefs: coefs_i32,
        // default domain = [-1, 1]
        domain: Interval { min: -1, max: 1 },
        // default window = [-1, 1]
        window: Interval { min: -1, max: 1 },
    }
}